// ui.js
// Displays the drag-and-drop UI
// --------------------------------------------------

import { useState, useRef, useCallback } from 'react';
import ReactFlow, { Controls, Background, MiniMap } from 'reactflow';
import { useStore } from './store';
import { shallow } from 'zustand/shallow';
import { InputNode } from './nodes/inputNode';
import { LLMNode } from './nodes/llmNode';
import { OutputNode } from './nodes/outputNode';
import { TextNode } from './nodes/textNode';
import { MathNode } from './nodes/mathNode';
import { APINode } from './nodes/apiNode';
import { ConditionNode } from './nodes/conditionNode';
import { CSVNode } from './nodes/csvNode';
import { CustomNode } from './nodes/customNode';

import 'reactflow/dist/style.css';

const gridSize = 20;
const proOptions = { hideAttribution: true };

// Color mapping for each node type
const NODE_COLORS = {
  customInput: { header: '#0ea5e9', bg: '#f0f9ff' }, // Blue
  llm: { header: '#8b5cf6', bg: '#f3e8ff' },         // Purple
  customOutput: { header: '#ec4899', bg: '#fdf2f8' }, // Pink
  text: { header: '#10b981', bg: '#f0fdf4' },         // Green
  math: { header: '#f59e0b', bg: '#fffbeb' },         // Amber
  api: { header: '#3b82f6', bg: '#dbeafe' },          // Light Blue
  condition: { header: '#ef4444', bg: '#fef2f2' },    // Red
  csv: { header: '#059669', bg: '#f0fdf4' },          // Emerald
  custom: { header: '#6b7280', bg: '#f3f4f6' },       // Gray
};

const nodeTypes = {
  customInput: InputNode,
  llm: LLMNode,
  customOutput: OutputNode,
  text: TextNode,
  math: MathNode,        
  api: APINode,          
  condition: ConditionNode, 
  csv: CSVNode,          
  custom: CustomNode,    
};

// Selector updated to include selectedNode
const selector = (state) => ({
  nodes: state.nodes,
  edges: state.edges,
  selectedNode: state.selectedNode, // ← Added
  getNodeID: state.getNodeID,
  addNode: state.addNode,
  onNodesChange: state.onNodesChange,
  onEdgesChange: state.onEdgesChange,
  onConnect: state.onConnect,
  setSelectedNode: state.setSelectedNode, // ← Added
});

export const PipelineUI = () => {
    const reactFlowWrapper = useRef(null);
    const [reactFlowInstance, setReactFlowInstance] = useState(null);
    const {
      nodes,
      edges,
      selectedNode, // ← Added
      setSelectedNode, // ← Added
      getNodeID,
      addNode,
      onNodesChange,
      onEdgesChange,
      onConnect
    } = useStore(selector, shallow);

    const getInitNodeData = (nodeID, type) => {
      let nodeData = { id: nodeID, nodeType: `${type}` };
      return nodeData;
    }

    // Handle node selection
    const onNodeClick = useCallback((event, node) => {
      setSelectedNode(node);
    }, [setSelectedNode]);

    const onDrop = useCallback(
        (event) => {
          event.preventDefault();

          const reactFlowBounds = reactFlowWrapper.current.getBoundingClientRect();
          if (event?.dataTransfer?.getData('application/reactflow')) {
            const appData = JSON.parse(event.dataTransfer.getData('application/reactflow'));
            const type = appData?.nodeType;

            // check if the dropped element is valid
            if (typeof type === 'undefined' || !type) {
              return;
            }

            const position = reactFlowInstance.project({
              x: event.clientX - reactFlowBounds.left,
              y: event.clientY - reactFlowBounds.top,
            });

            const nodeID = getNodeID(type);
            const newNode = {
              id: nodeID,
              type,
              position,
              data: getInitNodeData(nodeID, type),
            };

            addNode(newNode);
          }
        },
        [reactFlowInstance]
    );

    const onDragOver = useCallback((event) => {
        event.preventDefault();
        event.dataTransfer.dropEffect = 'move';
    }, []);

    // Node Preview Panel Component (inline)
    const NodePreviewPanel = () => {
      if (!selectedNode) {
        return (
          <div style={{
            width: '300px',
            padding: '16px',
            backgroundColor: '#f8fafc',
            borderRadius: '8px',
            border: '1px solid #e5e7eb',
            fontFamily: "'Inter', sans-serif",
          }}>
            <p style={{ fontSize: '12px', color: '#6b7280', textAlign: 'center' }}>Select a node to view its properties</p>
          </div>
        );
      }

      const colors = NODE_COLORS[selectedNode.type] || NODE_COLORS.custom;

      return (
        <div style={{
          width: '300px',
          padding: '16px',
          backgroundColor: colors.bg,
          borderLeft: `4px solid ${colors.header}`,
          fontFamily: "'Inter', sans-serif",
          borderRadius: '8px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.05)',
        }}>
          <h3 style={{
            margin: '0 0 12px 0',
            padding: '8px 12px',
            backgroundColor: colors.header,
            color: 'white',
            borderRadius: '4px',
            fontSize: '14px',
            fontWeight: 600,
          }}>
            {selectedNode.data.label || selectedNode.type}
          </h3>

          {/* Render node-specific fields */}
          {selectedNode.type === 'customInput' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Field Name</label>
              <input
                type="text"
                defaultValue={selectedNode.data.fieldName || "input"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'llm' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Model</label>
              <select
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              >
                <option>GPT-4</option>
                <option>Claude-3</option>
                <option>Llama-3</option>
              </select>
            </div>
          )}

          {selectedNode.type === 'text' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Text</label>
              <textarea
                defaultValue={selectedNode.data.text || ""}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                  resize: 'none',
                  minHeight: '60px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'math' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Formula</label>
              <input
                type="text"
                defaultValue={selectedNode.data.formula || "a + b"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'api' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>URL</label>
              <input
                type="text"
                defaultValue={selectedNode.data.url || "https://api.example.com"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'condition' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Condition</label>
              <input
                type="text"
                defaultValue={selectedNode.data.condition || "input > 10"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'csv' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>File Path</label>
              <input
                type="text"
                defaultValue={selectedNode.data.path || "./data.csv"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}

          {selectedNode.type === 'custom' && (
            <div>
              <label style={{ display: 'block', marginBottom: '4px', fontSize: '12px', color: '#374151' }}>Function</label>
              <input
                type="text"
                defaultValue={selectedNode.data.function || "myFunction"}
                style={{
                  width: '100%',
                  padding: '6px',
                  border: `1px solid ${colors.header}`,
                  borderRadius: '4px',
                  fontSize: '12px',
                }}
              />
            </div>
          )}
        </div>
      );
    };

    return (
        <>
        <div ref={reactFlowWrapper} style={{width: '100wv', height: '70vh'}}>
            <ReactFlow
                nodes={nodes}
                edges={edges}
                onNodesChange={onNodesChange}
                onEdgesChange={onEdgesChange}
                onConnect={onConnect}
                onDrop={onDrop}
                onDragOver={onDragOver}
                onInit={setReactFlowInstance}
                nodeTypes={nodeTypes}
                proOptions={proOptions}
                snapGrid={[gridSize, gridSize]}
                connectionLineType='smoothstep'
                onNodeClick={onNodeClick} // ← Added node click handler
            >
                <Background color="#aaa" gap={gridSize} />
                <Controls />
                <MiniMap />
            </ReactFlow>
        </div>
        {/* Node Preview Panel */}
        <div style={{ position: 'absolute', right: '20px', top: '20px', zIndex: 100 }}>
          <NodePreviewPanel />
        </div>
        </>
    )
}
